import "server-only";

// Storage keys are generated by the server ("<folder>/<yyyy>/<file id>.<ext>", see saveFile in
// uploads.ts) and are the same for every backend: the path under UPLOAD_DIR on the local disk
// and the pathname in Vercel Blob, so stored files can be copied between the two one to one.

// Lowercase path segments of [a-z0-9_-], one extension on the last segment. No dots
// elsewhere, so "." and ".." segments are impossible; length matches files.storage_key.
const KEY_PATTERN = /^[a-z0-9_-]+(?:\/[a-z0-9_-]+)*\.[a-z0-9]{1,10}$/;
const MAX_KEY_LENGTH = 200;
// Device names Windows refuses as file names, whatever the extension.
const WINDOWS_RESERVED = /^(?:con|prn|aux|nul|com[0-9]|lpt[0-9])$/;

export class InvalidStorageKeyError extends Error {
  constructor(key: string) {
    super(`Invalid storage key: ${JSON.stringify(key)}`);
    this.name = "InvalidStorageKeyError";
  }
}

/** Throws InvalidStorageKeyError unless `key` is a well-formed storage key. */
export function assertStorageKey(key: string): void {
  if (typeof key !== "string" || key.length > MAX_KEY_LENGTH || !KEY_PATTERN.test(key)) {
    throw new InvalidStorageKeyError(String(key));
  }
  if (key.split("/").some((segment) => WINDOWS_RESERVED.test(segment.split(".")[0]))) {
    throw new InvalidStorageKeyError(key);
  }
}

/** Whether `key` is a well-formed storage key. */
export function isStorageKey(key: string): boolean {
  try {
    assertStorageKey(key);
    return true;
  } catch {
    return false;
  }
}

// The types uploads.ts stores (images are always re-encoded as JPEG); the rest for files
// copied from elsewhere.
const CONTENT_TYPES: Readonly<Record<string, string>> = {
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  mp4: "video/mp4",
  mov: "video/quicktime",
  webm: "video/webm",
  pdf: "application/pdf",
};

/** The MIME type a stored file is kept with, from its key's extension. */
export function contentTypeForKey(key: string): string {
  const extension = key.slice(key.lastIndexOf(".") + 1).toLowerCase();
  return CONTENT_TYPES[extension] ?? "application/octet-stream";
}
